final class AnswerFeedbackTest extends TestCase {
 private Services $services;private Answers $answers;private Feedback $feedback;private int $actor;private int $member;private int $forum;private int $topic;private int $reply;private array $owned=[];private array $tokens=[];private array $hooks;private mixed $settings;private object $missing;
 protected function setUp():void {
  global $wp_filter;$this->hooks=array_map(static fn(WP_Hook $h):WP_Hook=>clone $h,$wp_filter);$this->missing=new stdClass();$this->settings=get_option('fi_settings',$this->missing);update_option('fi_settings',['ai_enabled'=>false,'author_acceptance'=>true,'modules'=>['notifications'=>false,'knowledge'=>false]]);add_filter('pre_wp_mail',static fn()=>true);
  foreach(['actor'=>'administrator','member'=>'subscriber']as $property=>$role){$login='fi_feedback99_'.$property.'_'.bin2hex(random_bytes(8));$this->$property=(int)wp_insert_user(['user_login'=>$login,'user_email'=>$login.'@example.invalid','user_pass'=>'owned-only','role'=>$role]);self::assertGreaterThan(0,$this->$property);bbp_set_user_role($this->$property,$property==='actor'?bbp_get_keymaster_role():bbp_get_participant_role());}
  wp_set_current_user($this->actor);$this->services=new Services();$this->services->register();$this->forum=$this->remember((int)bbp_insert_forum(['post_title'=>'Owned answer feedback forum','post_author'=>$this->actor]));$this->topic=$this->remember((int)bbp_insert_topic(['post_title'=>'Owned cache invalidation question','post_content'=>'How to fix cache invalidation safely.','post_author'=>$this->actor,'post_parent'=>$this->forum],['forum_id'=>$this->forum]));$this->reply=$this->remember((int)bbp_insert_reply(['post_content'=>'Delete the expired transient after updating the source.','post_author'=>$this->actor,'post_parent'=>$this->topic],['forum_id'=>$this->forum,'topic_id'=>$this->topic]));$this->services->solutions->change($this->topic,$this->reply,'accept',$this->actor);
  $provider=new class($this->reply) implements ForumIntelligence\Contracts\TextProvider {public function __construct(private int $reply){}public function generate(string $instruction,array $evidence):array{return ['answer'=>'OWNED_GENERATED_FEEDBACK_CANARY: Delete the expired transient.','source_ids'=>[$this->reply]];}};
  $this->answers=new Answers(new LexicalSearch($this->services->store,$this->services->access,$this->services->solutions),$provider,$this->services->access,$this->services->store);$this->feedback=new Feedback($this->services->store,$this->services->access);wp_set_current_user($this->member);
 }
 private function remember(int $id):int{self::assertGreaterThan(0,$id);$this->owned[]=$id;return$id;}
 protected function tearDown():void {
  $s=$this->services->store;foreach($this->tokens as $token)delete_transient('fi_answer_feedback_'.$this->member.'_'.$token);$s->execute("DELETE FROM {$s->table('records')} WHERE kind='ai_feedback' AND owner_id=%d",[$this->member]);$s->execute("DELETE FROM {$s->table('events')} WHERE kind IN ('ai_feedback_submitted','ai_feedback_reviewed') AND object_id=%d",[$this->topic]);
  foreach(['ask','ai_feedback']as $feature)$s->execute("DELETE FROM {$s->table('limits')} WHERE bucket=%s",[hash('sha256',$this->member.':'.$feature)]);
  $s->execute("DELETE FROM {$s->table('cases')} WHERE reporter_id=%d",[$this->member]);$s->execute("DELETE FROM {$s->table('records')} WHERE kind='moderation_advisory' AND object_id=%d",[$this->topic]);$s->execute("DELETE FROM {$s->table('events')} WHERE kind='moderation_advisory_generated' AND object_id=%d",[$this->topic]);foreach($this->owned as $id)$s->execute("DELETE FROM {$s->table('links')} WHERE kind='relationship' AND (source_id=%d OR target_id=%d)",[$id,$id]);
  wp_set_current_user($this->actor);foreach(array_reverse($this->owned)as $id){$post=get_post($id);if($post&&(int)$post->post_author!==$this->actor)throw new RuntimeException('Refusing foreign feedback fixture');wp_delete_post($id,true);}if($this->settings===$this->missing)delete_option('fi_settings');else update_option('fi_settings',$this->settings);require_once ABSPATH.'wp-admin/includes/user.php';foreach([$this->member,$this->actor]as $id){$u=get_userdata($id);if($u&&!str_starts_with($u->user_login,'fi_feedback99_'))throw new RuntimeException('Refusing foreign feedback actor');wp_delete_user($id);}wp_set_current_user(0);global $wp_filter;$wp_filter=$this->hooks;
 }
 private function answer():array {$result=$this->answers->ask('cache invalidation',$this->member);self::assertSame('answered',$result['state']);self::assertMatchesRegularExpression('/^[a-f0-9]{32}$/D',$result['feedback_token']??'');$this->tokens[]=$result['feedback_token'];return$result;}
 private function submit(array $answer,string $value='missing_context'):array{return$this->answers->feedback($this->topic,$value,$this->member,$answer['feedback_token']);}
 private function denied(callable $f,int $status):void{try{$f();self::fail('Invalid feedback must refuse.');}catch(Failure $e){self::assertSame($status,$e->status);}}
 private function row():array{$s=$this->services->store;return$s->row("SELECT * FROM {$s->table('records')} WHERE kind='ai_feedback' AND owner_id=%d",[$this->member])??[];}
 public function testGeneratedAnswerOffersBoundedOwnerFeedbackWithoutCopyingContent():void {
  $a=$this->answer();self::assertSame(['saved'=>true],$this->submit($a));$row=$this->row();self::assertSame($this->topic,(int)$row['object_id']);$data=json_decode($row['payload'],true);self::assertSame('missing_context',$data['value']);self::assertSame('open',$data['state']);self::assertMatchesRegularExpression('/^[a-f0-9]{64}$/D',$data['response']);self::assertStringNotContainsString('OWNED_GENERATED_FEEDBACK_CANARY',$row['payload']);self::assertStringNotContainsString('How to fix',$row['payload']);self::assertCount(1,$this->feedback->listing($this->actor)['items']);
 }
 public function testAllFiveFeedbackChoicesUpdateOneResponseAndSameChoiceIsIdempotent():void {
  $a=$this->answer();$s=$this->services->store;foreach(array_keys(Feedback::labels())as $value){$this->submit($a,$value);$row=$this->row();self::assertSame($value,json_decode($row['payload'],true)['value']);$version=(int)$row['version'];$this->submit($a,$value);self::assertSame($version,(int)$this->row()['version']);}self::assertSame(1,(int)$s->row("SELECT COUNT(*) AS n FROM {$s->table('records')} WHERE kind='ai_feedback' AND owner_id=%d",[$this->member])['n']);
 }
 public function testUnissuedWrongActorWrongObjectAndExpiredTokensRefuse():void {
  $a=$this->answer();$this->denied(fn()=>$this->answers->feedback($this->topic,'helpful',$this->actor,$a['feedback_token']),404);$this->denied(fn()=>$this->answers->feedback($this->reply,'helpful',$this->member,$a['feedback_token']),404);$this->denied(fn()=>$this->answers->feedback($this->topic,'helpful',$this->member,str_repeat('a',32)),404);$this->denied(fn()=>$this->submit($a,'invented'),400);
  $key='fi_answer_feedback_'.$this->member.'_'.$a['feedback_token'];$receipt=get_transient($key);$receipt['issued']=time()-901;set_transient($key,$receipt,900);$this->denied(fn()=>$this->submit($a),404);self::assertSame([],$this->row());
 }
