 public function testAuditFailureRollsBackFeedbackAndAllowsRetry():void {
  $a=$this->answer();$filter=static function(string $sql):string{if(str_starts_with($sql,'INSERT INTO')&&str_contains($sql,'ai_feedback_submitted'))throw new Failure('owned_feedback_audit_failure','Owned native audit failure',503);return$sql;};add_filter('query',$filter,99);try{$this->denied(fn()=>$this->submit($a),503);}finally{remove_filter('query',$filter,99);}self::assertSame([],$this->row());self::assertSame(['saved'=>true],$this->submit($a));
