 public function testIndependentModerationProviderDoesNotRequireTextGenerationContract():void {
  $this->services->get('cases')->report($this->topic,$this->member,'spam','Owned review only');$case=(int)$this->services->get('cases')->listing($this->actor)['items'][0]['id'];$provider=new class($this->topic) implements ForumIntelligence\Contracts\ModerationProvider {public int $calls=0;public function __construct(private int $source){}public function assess(array $evidence):array{++$this->calls;return ['answer'=>wp_json_encode(['spam'=>0.1,'toxicity'=>0.1,'dangerous'=>0.1,'pii'=>0.1,'confidence'=>0.9,'explanation'=>'Independent advisory only.','recommendation'=>'no_flag']),'source_ids'=>[$this->source]];}};
  self::assertNotInstanceOf(ForumIntelligence\Contracts\TextProvider::class,$provider);$advisory=new ForumIntelligence\Domain\Moderation\Advisory($this->services->store,$this->services->queue,$this->services->access,$provider);$advisory->generate($case,$this->actor);self::assertSame(1,$provider->calls);self::assertTrue($advisory->view($case,$this->actor)['advisory_only']);self::assertSame('publish',get_post_status($this->topic));
