 public function testRerankingIsOffUnlessBothConsentAndFeatureAreRealBooleans():void {
  $provider=new class($this->topic,$this->reply) implements ForumIntelligence\Contracts\RerankingProvider {public int $calls=0;public array $evidence=[];public function __construct(private int $topic,private int $reply){}public function rerank(string $query,array $evidence):array{++$this->calls;$this->evidence=$evidence;return[$this->topic=>0.1,$this->reply=>0.9];}};
