  update_option('fi_settings',['ai_enabled'=>true,'reranking'=>true]);$result=$search->search('cache',[],$this->member);self::assertSame(1,$provider->calls);self::assertSame([$this->reply,$this->topic],array_column($result['items'],'id'));self::assertCount(2,$provider->evidence);self::assertSame(['id','text'],array_keys($provider->evidence[0]));wp_update_post(['ID'=>$this->topic,'post_password'=>'owned-rerank-private']);$search->search('cache',[],$this->member);self::assertSame(1,$provider->calls);
