 public function testFeatureModelsAndHttpBoundsUseNativeInterceptedTransport():void {
  $s=$this->services->store;$bucket=hash('sha256','0:ai_daily');$budget=$s->rows("SELECT * FROM {$s->table('limits')} WHERE bucket=%s",[$bucket]);$s->execute("DELETE FROM {$s->table('limits')} WHERE bucket=%s",[$bucket]);$endpoint=defined('FI_AI_ENDPOINT')?(string)constant('FI_AI_ENDPOINT'):'https://api.openai.com/v1';$circuit='fi_ai_outage_'.substr(hash('sha256',$endpoint),0,16);$missing=new stdClass();$saved=[get_option('_transient_'.$circuit,$missing),get_option('_transient_timeout_'.$circuit,$missing)];delete_transient($circuit);$calls=[];
  $http=static function($pre,array $args,string $url)use(&$calls){$body=json_decode($args['body'],true);$calls[]=['model'=>$body['model'],'timeout'=>$args['timeout'],'tokens'=>$body['max_completion_tokens']];return['headers'=>[],'body'=>wp_json_encode(['choices'=>[['message'=>['content'=>wp_json_encode(['answer'=>'Owned response','source_ids'=>[1]])]]]]),'response'=>['code'=>200,'message'=>'OK'],'cookies'=>[]];};add_filter('pre_http_request',$http,99,3);update_option('fi_settings',['ai_enabled'=>true,'summary_model'=>'owned-summary','moderation_model'=>'owned-moderation','reranking_model'=>'owned-reranking','ai_timeout_seconds'=>999,'ai_completion_tokens'=>99999]);
  try{foreach(['summary','moderation','reranking']as $feature)(new ForumIntelligence\Infrastructure\AI\OpenAICompatible($s,$feature))->generate('Owned instruction',[['id'=>1,'text'=>'Owned evidence']]);self::assertSame([['model'=>'owned-summary','timeout'=>30,'tokens'=>4096],['model'=>'owned-moderation','timeout'=>30,'tokens'=>4096],['model'=>'owned-reranking','timeout'=>30,'tokens'=>4096]],$calls);}finally{remove_filter('pre_http_request',$http,99);$s->execute("DELETE FROM {$s->table('limits')} WHERE bucket=%s",[$bucket]);foreach($budget as $row)$s->execute("INSERT INTO {$s->table('limits')} (bucket,window_start,count) VALUES (%s,%d,%d)",[$row['bucket'],$row['window_start'],$row['count']]);foreach(['_transient_'.$circuit,'_transient_timeout_'.$circuit]as $i=>$key){if($saved[$i]===$missing)delete_option($key);else update_option($key,$saved[$i]);}}
 }
 public function testRelationshipAuditFailureCannotLeaveAnApprovedEdge():void {
