 public function testTextRerankingBridgeRejectsFabricatedIdsAndMalformedCitations():void {
  $provider=new class implements ForumIntelligence\Contracts\TextProvider {public array $result=[];public function generate(string $instruction,array $evidence):array{return$this->result;}};
  $bridge=new ForumIntelligence\Infrastructure\AI\TextRerankingProvider($provider);$evidence=[['id'=>1,'text'=>'Owned first'],['id'=>2,'text'=>'Owned second']];
  foreach([['answer'=>'{"scores":[{"id":1,"score":0.1},{"id":2,"score":0.9}]}','source_ids'=>[[1],2]],['answer'=>'{"scores":[{"id":1,"score":0.1},{"id":99,"score":0.9}]}','source_ids'=>[1,2]],['answer'=>'{"scores":[{"id":1,"score":0.1},{"id":1,"score":0.9}]}','source_ids'=>[1,2]]]as $invalid){$provider->result=$invalid;$this->denied(fn()=>$bridge->rerank('Owned query',$evidence),503);}
  $provider->result=['answer'=>'{"scores":[{"id":1,"score":0.1},{"id":2,"score":0.9}]}','source_ids'=>[1,2]];self::assertSame([1=>0.1,2=>0.9],$bridge->rerank('Owned query',$evidence));
 }
