  update_option('fi_settings',['index_pending'=>true,'semantic'=>true]);$index->index($this->topic);$row=$s->row("SELECT visibility,vector,content FROM {$s->table('chunks')} WHERE source_id=%d",[$this->topic]);self::assertNotNull($row);self::assertSame('restricted',$row['visibility']);self::assertSame('[]',$row['vector']);self::assertStringContainsString('cache invalidation',$row['content']);self::assertSame(0,$provider->calls);
  $search=new LexicalSearch($s,$this->services->access,$this->services->solutions);foreach([0,$this->member,$this->actor]as$user){$result=$search->search('cache invalidation',['object_id'=>$this->topic],$user);self::assertNotContains($this->topic,array_column($result['items'],'id'));}update_option('fi_settings',['index_pending'=>false]);$index->index($this->topic);self::assertNull($s->row("SELECT source_id FROM {$s->table('chunks')} WHERE source_id=%d",[$this->topic]));self::assertSame('pending',get_post_status($this->topic));
  update_option('fi_settings',['index_pending'=>true,'semantic'=>true]);wp_update_post(['ID'=>$this->topic,'post_status'=>'publish']);$index->index($this->topic);self::assertSame(1,$provider->calls);self::assertContains($this->topic,array_column($search->search('cache invalidation',[],$this->member)['items'],'id'));
